mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.RG_DT DESC) AS LISTNUM, A.FRM_UNQ_KY_VAL, A.FRM_ID, A.TITL_NM, A.TH1_ITM_NM, A.TH2_ITM_NM, A.TH3_ITM_NM, A.STDVL_VAL_NM, A.UNIT_NM, A.CNIF_YN, CASE WHEN A.CNIF_YN = 'Y' THEN '연계' WHEN A.CNIF_YN = 'N' THEN '미연계' ELSE '' END AS FM_CNIF_YN, A.CNIF_TAG_NM, A.REGPR_ID, A.REGPR_NM, A.RG_DT, TO_CHAR(A.RG_DT, 'YYYY-MM-DD') AS FM_RG_DT FROM GE_MP_FRMID_M A JOIN GE_MP_FRM_M B ON A.FRM_UNQ_KY_VAL = B.FRM_UNQ_KY_VAL AND B.FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}
AND A.TITL_NM LIKE '%'||#{TITL_NM}||'%'
AND (A.TH1_ITM_NM LIKE '%'||#{SH_ITM_NM}||'%' OR A.TH2_ITM_NM LIKE '%'||#{SH_ITM_NM}||'%' OR A.TH2_ITM_NM LIKE '%'||#{SH_ITM_NM}||'%')
ORDER BY A.RG_DT DESC ) WHERE LISTNUM BETWEEN #{DISPSTART} AND #{DISPEND}

